    void *object,
    __attribute__((swift_context)) void *coderMetadata,
    __attribute__((swift_error_result)) void **errorOut
);
typedef __attribute__((swiftcall)) void *(*MacIslandReplicatorDecodeFn)(
    void *targetMetadata,
    uint64_t dataW0,
